local function getQuestLabel()
    local gui = player:WaitForChild('PlayerGui')
    local general = gui:WaitForChild('General')
    local quest = general:WaitForChild('Quest')
    local main = quest:WaitForChild('Main')
    local frame = main:WaitForChild('Frame')
    local frames = frame:WaitForChild('Frames')
    local activated = frames:WaitForChild('Activated')
    local desc = activated:WaitForChild('Description')

    return desc
end

