wTab:CreateToggle({
    Name = 'Auto Use Power',
    CurrentValue = false,
    Flag = 'AutoPowerClick',
    Callback = function(Value)
        if Value then
            spawn(function()
                print('Auto Power Click \u{2192} ON')

                while Toggle.CurrentValue do
                    local char = player.Character

                    if char and char:FindFirstChild('Humanoid') and char.Humanoid.Health > 0 then
                        local equippedTool = char:FindFirstChildOfClass('Tool')

                        if not equippedTool then
                            local backpack = player.Backpack
                            local firstTool = backpack:FindFirstChildOfClass('Tool')

                            if firstTool then
                                firstTool.Parent = char

                                task.wait(0.18)
                                print('First tool equipped \u{2192} using power')
                            else
                                print('No tool in backpack.')
                                task.wait(1)

                                continue
                            end
                        end

                        local success, result = pcall(function()
                            return Remote:InvokeServer(unpack(args))
                        end)

                        if success then
                            print('Power Click fired \u{2192}', result or 'SUCCESS (nil = usually good)')
                        else
                            warn('InvokeServer crashed:', result)
                        end
                    end

                    task.wait(0.06)
                end

                print('Auto Power \u{2192} stopped')
            end)
        else
            print('Auto Power \u{2192} OFF')
        end
    end,
})

