wTab:CreateToggle({
    Name = 'Monster Bringer',
    CurrentValue = false,
    Flag = 'CloudTowerMonsterBringer',
    Callback = function(Value)
        if Value then
            print('CloudTowerMonster Bringer \u{2192} ON')
            spawn(function()
                local localCopies = {}

                while Toggle.CurrentValue do
                    for _, obj in ipairs(workspace:GetChildren())do
                        if obj.Name == 'CloudTowerMonster' and not localCopies[obj] then
                            local fakeClone = obj:Clone()

                            fakeClone.Parent = workspace

                            if fakeClone:IsA('Model') then
                                for _, part in ipairs(fakeClone:GetDescendants())do
                                    if part:IsA('BasePart') then
                                        part.CanCollide = false
                                        part.Anchored = true
                                        part.Transparency = 0.3
                                        part.Color = Color3.fromRGB(200, 255, 255)
                                    end
                                end
                            end
                            if fakeClone.PrimaryPart and obj.PrimaryPart then
                                fakeClone:SetPrimaryPartCFrame(obj.PrimaryPart.CFrame)
                            elseif fakeClone:FindFirstChild('HumanoidRootPart') and obj:FindFirstChild('HumanoidRootPart') then
                                fakeClone.HumanoidRootPart.CFrame = obj.HumanoidRootPart.CFrame
                            end

                            localCopies[obj] = fakeClone

                            print('Brought CloudTowerMonster ')
                        end
                    end
                    for serverObj, clientClone in pairs(localCopies)do
                        if serverObj.Parent and clientClone.Parent then
                            if serverObj.PrimaryPart and clientClone.PrimaryPart then
                                clientClone:SetPrimaryPartCFrame(serverObj.PrimaryPart.CFrame)
                            end
                        else
